#!/usr/bin/env bash
# GENERATED by rr7-starter/scripts/devcontainer-sync.mjs — do not edit here. Change devcontainer-template/sbx/ (shared) or .sbx/project.json (this project), then re-run.
# Give the panel sandbox (or any other) a proxied secret at any time, even one
# that is already running. Run it on the HOST.
#
#   ./.sbx/secret.sh --host api.example.com --env EXAMPLE_API_KEY --command 'op read op://Vault/Example/key'
#   ./.sbx/secret.sh --host gitlab.com --env GITLAB_TOKEN --command 'glab auth token'
#   ./.sbx/secret.sh --sandbox panel-codex --host ... --env ... --command ...
#   ./.sbx/secret.sh --global --sandbox panel --sandbox panel-codex --host ... --env ... --command ...
#
# `sbx secret set-custom` on its own only reaches sandboxes created after it: the
# env var holding the placeholder is set at creation. The proxy picks a new secret
# up straight away, so an existing sandbox is only missing that variable. This
# script registers the secret with a placeholder it chooses, then writes
# `export VAR=<placeholder>` into the sandbox's /etc/sandbox-persistent.sh, which
# every bash process there sources (Claude Code before each command too). The
# placeholder is not a secret; the real value stays on the host.
#
# Every argument except --sandbox and --global goes to `sbx secret set-custom`.
# Prefer --command or --ref over --value (a value on the command line lands in
# shell history). Remove a secret with `sbx secret rm --host <host>`.
set -euo pipefail

die() { echo "sbx secret: $*" >&2; exit 1; }

SANDBOXES=()
GLOBAL=""
VAR=""
ARGS=()
while [ $# -gt 0 ]; do
  case "$1" in
    --sandbox) SANDBOXES+=("${2:?--sandbox needs a name}"); shift 2 ;;
    --global) GLOBAL=1; shift ;;
    --placeholder) die "--placeholder is chosen by this script" ;;
    --env) VAR="${2:?--env needs a variable name}"; ARGS+=("$1" "$2"); shift 2 ;;
    *) ARGS+=("$1"); shift ;;
  esac
done

command -v sbx >/dev/null || die "sbx CLI not found"
[[ "$VAR" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || die "--env <VAR> is required (a shell variable name)"
[ ${#SANDBOXES[@]} -gt 0 ] || SANDBOXES=("panel")
[ -n "$GLOBAL" ] || [ ${#SANDBOXES[@]} -eq 1 ] || die "a sandbox-scoped secret has one --sandbox; use --global to share it"

# 1. Register. A fresh placeholder each time, so rerunning also rotates it.
PH="sbx-cs-$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n')"
SCOPE=()
[ -n "$GLOBAL" ] || SCOPE=(--sandbox "${SANDBOXES[0]}")
sbx secret set-custom "${ARGS[@]}" --placeholder "$PH" "${SCOPE[@]+"${SCOPE[@]}"}"

# 2. Hand the placeholder to each sandbox, replacing any earlier line for VAR.
for sb in "${SANDBOXES[@]}"; do
  if sbx exec "$sb" sh -c '
      f=/etc/sandbox-persistent.sh
      { grep -v "^export $1=" "$f" 2>/dev/null || true; echo "export $1=$2"; } > "$f.new"
      cat "$f.new" > "$f" && rm -f "$f.new"' sh "$VAR" "$PH"; then
    echo ">>> $sb: $VAR is set for new shells and Claude Code's next command"
  else
    echo ">>> $sb: not reachable (not created yet, or stopped)."
    echo "    Not created yet: nothing more to do, the variable is set when it is created."
    echo "    Stopped: start it and rerun this command."
  fi
done
